52	Status FabricMemAllocator::MallocMem(MemType type, size_t size, void **ptr) {
53	  HIXL_CHK_BOOL_RET_STATUS(type == MemType::MEM_HOST || type == MemType::MEM_DEVICE, PARAM_INVALID,
