62	  uintptr_t virtual_addr = 0;
63	  HIXL_CHK_STATUS_RET(AllocatePhysicalMemory(type, size, logic_device_id, pa_handle),
64	                      "Failed to allocate physical memory.");
65	  HIXL_DISMISSABLE_GUARD(
66	      free_pa_guard, ([&pa_handle]() { HIXL_CHK_ACL(aclrtFreePhysical(pa_handle), "Free physical memory failed."); }));
67	  HIXL_CHK_STATUS_RET(VirtualMemoryManager::GetInstance().ReserveMemory(size, virtual_addr),
68	                      "Failed to reserve virtual memory.");
69	  HIXL_DISMISSABLE_GUARD(
70	      release_va_guard, ([&virtual_addr]() { (void)VirtualMemoryManager::GetInstance().ReleaseMemory(virtual_addr); }));
71	  const auto va_ptr = reinterpret_cast<void *>(virtual_addr);
72	  HIXL_CHK_ACL_RET(aclrtMapMem(va_ptr, size, 0, pa_handle, 0), "Map fabric memory failed.");
73	  HIXL_DISMISSABLE_GUARD(unmap_guard,
74	                         ([va_ptr]() { HIXL_CHK_ACL(aclrtUnmapMem(va_ptr), "Unmap fabric memory failed."); }));
75	  if (type == MemType::MEM_HOST) {
