97	  (void)VirtualMemoryManager::GetInstance().ReleaseMemory(va_addr);
98	  HIXL_CHK_ACL(aclrtFreePhysical(pa_handle), "Free physical memory failed.");
99	  HIXL_LOGI("FreeFabricMemory success, va:%lu.", va_addr);
