103	Status FabricMemAllocator::AllocatePhysicalMemory(MemType type, size_t total_size, int32_t logic_device_id,
104	                                                  aclrtDrvMemHandle &handle) {
105	  HIXL_CHK_BOOL_RET_STATUS(type == MemType::MEM_HOST || type == MemType::MEM_DEVICE, PARAM_INVALID,
106	                           "Invalid fabric memory type:%d.", static_cast<int32_t>(type));
107	  aclrtPhysicalMemProp prop = BuildDefaultPhysicalMemProp();
108	  if (type == MemType::MEM_DEVICE) {
109	    prop.memAttr = ACL_HBM_MEM_HUGE;
110	    prop.location.type = ACL_MEM_LOCATION_TYPE_DEVICE;
111	    prop.location.id = logic_device_id;
112	    HIXL_CHK_ACL_RET(aclrtMallocPhysical(&handle, total_size, &prop, 0), "Allocate device physical memory failed.");
113	    return SUCCESS;
114	  }
115	
116	  int32_t physical_device_id = 0;
117	  HIXL_CHK_ACL_RET(aclrtGetPhyDevIdByLogicDevId(logic_device_id, &physical_device_id),
118	                   "Get physical device id failed.");
119	  prop.memAttr = ACL_MEM_P2P_HUGE1G;
120	  prop.location.type = ACL_MEM_LOCATION_TYPE_HOST_NUMA;
121	  prop.location.id = (physical_device_id / kDevicesPerChip) * kNumaNodeStep;
122	  HIXL_LOGI("Malloc host memory for numa:%d.", prop.location.id);
123	  auto ret = aclrtMallocPhysical(&handle, total_size, &prop, 0);
124	  if (ret == ACL_ERROR_NONE) {
125	    return SUCCESS;
126	  }
127	  HIXL_LOGI("Try common host allocation instead of numa:%d.", prop.location.id);
128	  prop.location.type = ACL_MEM_LOCATION_TYPE_HOST;
129	  prop.location.id = 0;
130	  ret = aclrtMallocPhysical(&handle, total_size, &prop, 0);
131	  if (ret == ACL_ERROR_NONE) {
132	    return SUCCESS;
133	  }
134	  HIXL_LOGI("Try smaller page instead of 1G page.");
135	  prop.memAttr = ACL_MEM_P2P_HUGE;
136	  HIXL_CHK_ACL_RET(aclrtMallocPhysical(&handle, total_size, &prop, 0), "Allocate physical memory failed.");
137	  return SUCCESS;
