25	constexpr uint64_t kHostFlagInitValue = 0ULL;
26	constexpr size_t kHostFlagSize = sizeof(uint64_t);
27	constexpr uint32_t kA3NotifyIdLimit = 1U << 13U;
28	
29	uint64_t GetDurationUs(const std::chrono::steady_clock::time_point &start,
30	                       const std::chrono::steady_clock::time_point &end) {
31	  return static_cast<uint64_t>(std::chrono::duration_cast<std::chrono::microseconds>(end - start).count());
32	}
33	
34	// Every request in `requests` is a view onto the same pooled entry as `slot`, so any of them can drive
35	// the abort. Falling back to a request keeps the "stop the kernel before freeing its buffers" rule even
36	// if a caller hands over an already-cleared slot.
37	const AsyncSlot *PickAbortSlot(const AsyncSlot &slot, const std::vector<FabricMemAicpuPendingRequest> &requests) {
38	  if (slot.ctx != nullptr) {
39	    return &slot;
40	  }
41	  for (const auto &request : requests) {
42	    if ((request.slot != nullptr) && (request.slot->ctx != nullptr)) {
43	      return request.slot;
44	    }
45	  }
46	  return nullptr;
47	}
48	}  // namespace
49	
50	FabricMemSlotPool::~FabricMemSlotPool() {
51	  AbortAndDestroyAll();
52	}
53	
54	Status FabricMemSlotPool::Initialize(int32_t device_id, size_t max_async_slot_num, size_t task_stream_num) {
55	  HIXL_CHK_BOOL_RET_STATUS(device_id >= 0, PARAM_INVALID, "device_id must be non-negative.");
56	  HIXL_CHK_BOOL_RET_STATUS(max_async_slot_num > 0, PARAM_INVALID, "max_async_slot_num must be greater than zero.");
57	  HIXL_CHK_BOOL_RET_STATUS(task_stream_num > 0, PARAM_INVALID, "task_stream_num must be greater than zero.");
58	  device_id_ = device_id;
59	  max_async_slot_num_ = max_async_slot_num;
60	  task_stream_num_ = task_stream_num;
61	  return SUCCESS;
62	}
63	
64	Status FabricMemSlotPool::CreateSlotStream(aclrtStream &stream) {
65	  stream = nullptr;
66	  HIXL_CHK_ACL_RET(aclrtCreateStreamWithConfig(&stream, 0, ACL_STREAM_FAST_LAUNCH | ACL_STREAM_FAST_SYNC),
67	                   "Create fabric mem stream failed.");
68	  HIXL_DISMISSABLE_GUARD(stream_guard, ([&stream]() {
69	                           HIXL_CHK_ACL(aclrtDestroyStream(stream), "Destroy fabric mem stream failed.");
70	                           stream = nullptr;
71	                         }));
72	  HIXL_CHK_ACL_RET(aclrtSetStreamFailureMode(stream, ACL_STOP_ON_FAILURE),
73	                   "Set fabric mem stream failure mode failed.");
74	  HIXL_DISMISS_GUARD(stream_guard);
75	  return SUCCESS;
76	}
77	
78	Status FabricMemSlotPool::CreateAicpuRtsqStream(aclrtStream &stream) {
79	  stream = nullptr;
80	  // DEVICE_USE_ONLY rejects aclrtSetStreamFailureMode (ACL_ERROR_RT_FEATURE_NOT_SUPPORT / 207000).
81	  HIXL_CHK_ACL_RET(aclrtCreateStreamWithConfig(&stream, 0U, ACL_STREAM_DEVICE_USE_ONLY),
82	                   "Create FabricMem AICPU RTSQ worker stream failed.");
83	  return SUCCESS;
84	}
85	
86	void FabricMemSlotPool::DestroySlotStreams(std::vector<aclrtStream> &streams, bool abort_streams, bool device_only) {
87	  for (auto &stream : streams) {
88	    if (stream == nullptr) {
89	      continue;
90	    }
91	    if (abort_streams) {
92	      if (device_only) {
93	        HIXL_CHK_ACL(aclrtStreamStop(stream), "Stop FabricMem AICPU RTSQ worker stream failed.");
94	      } else {
95	        HIXL_CHK_ACL(aclrtStreamAbort(stream), "Abort fabric mem stream failed.");
96	      }
97	    }
98	    HIXL_CHK_ACL(aclrtDestroyStream(stream), "Destroy fabric mem stream failed.");
99	    stream = nullptr;
100	  }
101	  streams.clear();
102	}
103	
104	void FabricMemSlotPool::DestroySlotNotifies(std::vector<aclrtNotify> &notifies, std::vector<uint32_t> &notify_ids) {
105	  for (auto &notify : notifies) {
106	    if (notify != nullptr) {
107	      HIXL_CHK_ACL(aclrtDestroyNotify(notify), "Destroy FabricMem AICPU notify failed.");
108	      notify = nullptr;
109	    }
110	  }
111	  notifies.clear();
112	  notify_ids.clear();
113	}
114	
115	void FabricMemSlotPool::DestroySlotHostFlags(std::vector<void *> &host_flags) {
116	  for (void *host_flag : host_flags) {
117	    if (host_flag != nullptr) {
118	      HIXL_CHK_ACL(aclrtFreeHost(host_flag), "Free fabric mem host flag failed.");
119	    }
120	  }
121	  host_flags.clear();
122	}
123	
124	void FabricMemSlotPool::ResetSlotHostFlags(const std::vector<void *> &host_flags) {
125	  for (void *host_flag : host_flags) {
126	    if (host_flag != nullptr) {
127	      *static_cast<uint64_t *>(host_flag) = kHostFlagInitValue;
128	    }
129	  }
130	}
131	
132	void FabricMemSlotPool::DestroyCreatedSlotEntry(AsyncSlot &entry) {
133	  if (entry.ctx == nullptr) {
134	    return;
135	  }
136	  TemporaryRtContext with_context(entry.ctx);
137	  DestroySlotStreams(entry.sdma_streams, false, true);
138	  DestroySlotStreams(entry.streams, false);
139	  DestroySlotNotifies(entry.notifies, entry.notify_ids);
140	  DestroySlotHostFlags(entry.host_flags);
141	  HIXL_CHK_ACL(aclrtDestroyContext(entry.ctx), "Destroy fabric mem transfer context failed.");
142	  entry.ctx = nullptr;
143	}
144	
145	Status FabricMemSlotPool::PopulateSlotStreams(AsyncSlot &entry) const {
146	  entry.streams.clear();
147	  entry.streams.reserve(task_stream_num_);
148	  for (size_t i = 0U; i < task_stream_num_; ++i) {
149	    aclrtStream stream = nullptr;
150	    HIXL_CHK_STATUS_RET(CreateSlotStream(stream), "Create fabric mem stream failed.");
151	    entry.streams.emplace_back(stream);
152	  }
153	  return SUCCESS;
154	}
155	
156	Status FabricMemSlotPool::PopulateAicpuRtsqStreams(AsyncSlot &entry) const {
157	  entry.sdma_streams.clear();
158	  entry.sdma_streams.reserve(task_stream_num_);
159	  for (size_t i = 0U; i < task_stream_num_; ++i) {
160	    aclrtStream stream = nullptr;
161	    HIXL_CHK_STATUS_RET(CreateAicpuRtsqStream(stream), "Create FabricMem AICPU RTSQ worker stream failed.");
162	    entry.sdma_streams.emplace_back(stream);
163	  }
164	  return SUCCESS;
165	}
166	
167	Status FabricMemSlotPool::PopulateAicpuNotifies(AsyncSlot &entry) const {
168	  entry.notifies.clear();
169	  entry.notify_ids.clear();
170	  entry.notifies.reserve(task_stream_num_);
171	  entry.notify_ids.reserve(task_stream_num_);
172	  for (size_t i = 0U; i < task_stream_num_; ++i) {
173	    aclrtNotify notify = nullptr;
174	    HIXL_CHK_ACL_RET(aclrtCreateNotify(&notify, ACL_NOTIFY_DEVICE_USE_ONLY), "Create FabricMem AICPU notify failed.");
175	    entry.notifies.emplace_back(notify);
176	    uint32_t notify_id = 0U;
177	    HIXL_CHK_ACL_RET(aclrtGetNotifyId(notify, &notify_id), "Get FabricMem AICPU notify id failed.");
178	    HIXL_CHK_BOOL_RET_STATUS(notify_id < kA3NotifyIdLimit, UNSUPPORTED,
179	                             "FabricMem AICPU notify id:%u exceeds the A3 13-bit ABI.", notify_id);
180	    entry.notify_ids.emplace_back(notify_id);
181	  }
182	  return SUCCESS;
183	}
184	
185	Status FabricMemSlotPool::PopulateSlotHostFlags(AsyncSlot &entry) const {
186	  entry.host_flags.clear();
187	  entry.host_flags.reserve(task_stream_num_);
188	  for (size_t i = 0U; i < task_stream_num_; ++i) {
189	    void *host_flag = nullptr;
190	    HIXL_CHK_ACL_RET(aclrtMallocHost(&host_flag, kHostFlagSize), "Allocate fabric mem host flag failed.");
191	    *static_cast<uint64_t *>(host_flag) = kHostFlagInitValue;
192	    entry.host_flags.emplace_back(host_flag);
193	  }
194	  return SUCCESS;
195	}
196	
197	Status FabricMemSlotPool::CreateSlotEntryLocked(AsyncSlot &entry) const {
198	  HIXL_CHK_ACL_RET(aclrtCreateContext(&entry.ctx, device_id_), "Create fabric mem transfer context failed.");
199	  HIXL_DISMISSABLE_GUARD(ctx_guard, ([&entry]() { DestroyCreatedSlotEntry(entry); }));
200	  TemporaryRtContext with_context(entry.ctx);
201	  HIXL_CHK_STATUS_RET(PopulateSlotStreams(entry), "Populate fabric mem slot streams failed.");
202	  HIXL_CHK_STATUS_RET(PopulateSlotHostFlags(entry), "Populate fabric mem slot host flags failed.");
203	  entry.available = true;
204	  HIXL_DISMISS_GUARD(ctx_guard);
205	  return SUCCESS;
206	}
207	
208	void FabricMemSlotPool::DestroySlotEntryLocked(AsyncSlot &entry, bool abort_streams) const {
209	  if (entry.ctx == nullptr) {
210	    return;
211	  }
212	  aclrtContext ctx = entry.ctx;
213	  entry.ctx = nullptr;
214	  {
215	    TemporaryRtContext with_context(ctx);
216	    DestroySlotStreams(entry.streams, abort_streams);
217	    DestroySlotStreams(entry.sdma_streams, abort_streams, true);
218	    DestroySlotNotifies(entry.notifies, entry.notify_ids);
219	    DestroySlotHostFlags(entry.host_flags);
220	  }
221	  HIXL_CHK_ACL(aclrtDestroyContext(ctx), "Destroy fabric mem transfer context failed.");
222	  entry.available = false;
223	}
224	
225	Status FabricMemSlotPool::TryAcquireSlotLocked(AsyncSlot &slot) {
226	  if (!free_slot_indices_.empty()) {
227	    const size_t idx = free_slot_indices_.front();
228	    free_slot_indices_.pop();
229	    auto &entry = slot_pool_[idx];
230	    entry.available = false;
231	    // Host flags are owned by the pooled entry and reused; clear stale completion
232	    // values before handing the slot out for the next transfer.
233	    ResetSlotHostFlags(entry.host_flags);
234	    slot.ctx = entry.ctx;
235	    slot.streams = entry.streams;
236	    slot.sdma_streams = entry.sdma_streams;
237	    slot.notifies = entry.notifies;
238	    slot.notify_ids = entry.notify_ids;
239	    slot.host_flags = entry.host_flags;
240	    slot.has_aicpu_unfold = false;
241	    return SUCCESS;
242	  }
243	  if (slot_pool_.size() >= max_async_slot_num_) {
244	    return FAILED;
245	  }
246	  AsyncSlot entry;
247	  const Status status = CreateSlotEntryLocked(entry);
248	  if (status != SUCCESS) {
249	    return status;
250	  }
251	  entry.available = false;
252	  slot.ctx = entry.ctx;
253	  slot.streams = entry.streams;
254	  slot.sdma_streams = entry.sdma_streams;
255	  slot.notifies = entry.notifies;
256	  slot.notify_ids = entry.notify_ids;
257	  slot.host_flags = entry.host_flags;
258	  slot.has_aicpu_unfold = false;
259	  slot_pool_.emplace_back(std::move(entry));
260	  return SUCCESS;
261	}
262	
263	Status FabricMemSlotPool::AcquireAsync(AsyncSlot &slot) {
264	  std::lock_guard<std::mutex> lock(pool_mutex_);
265	  slot.ctx = nullptr;
266	  slot.streams.clear();
267	  slot.sdma_streams.clear();
268	  slot.notifies.clear();
269	  slot.notify_ids.clear();
270	  slot.host_flags.clear();
271	  slot.has_aicpu_unfold = false;
272	  HIXL_CHK_STATUS_RET(TryAcquireSlotLocked(slot), "Failed to acquire fabric mem async transfer slot.");
273	  return SUCCESS;
274	}
275	
276	Status FabricMemSlotPool::AcquireWithTimeout(AsyncSlot &slot, uint64_t timeout_us) {
277	  const auto start = std::chrono::steady_clock::now();
278	  std::unique_lock<std::mutex> lock(pool_mutex_);
279	  while (true) {
280	    // When there is a free slot or room to grow, TryAcquireSlotLocked either succeeds (free path) or
281	    // fails only because slot creation (ACL stream/context) failed. Such a creation error is not pool
282	    // contention, so return it immediately instead of busy-retrying ACL calls until the timeout.
283	    if (!free_slot_indices_.empty() || slot_pool_.size() < max_async_slot_num_) {
284	      // TryAcquireSlotLocked leaves slot untouched on failure, so retries are safe.
285	      const Status status = TryAcquireSlotLocked(slot);
286	      if (status == SUCCESS) {
287	        return SUCCESS;
288	      }
289	      HIXL_LOGE(status, "Failed to create fabric mem transfer slot.");
290	      return status;
291	    }
292	    // Pool is full with nothing free: wait for a release (or timeout).
293	    const auto cost = GetDurationUs(start, std::chrono::steady_clock::now());
294	    HIXL_CHK_BOOL_RET_STATUS(cost < timeout_us, TIMEOUT,
295	                             "Get fabric mem transfer slot timed out, elapsed:%lu us, timeout:%lu us", cost,
296	                             timeout_us);
297	    const auto remaining = std::chrono::microseconds(timeout_us - cost);
298	    pool_cv_.wait_for(lock, remaining,
299	                      [this]() { return !free_slot_indices_.empty() || slot_pool_.size() < max_async_slot_num_; });
300	  }
301	}
302	
303	Status FabricMemSlotPool::EnsureAicpuRtsqStreams(AsyncSlot &slot) {
304	  HIXL_CHK_BOOL_RET_STATUS(slot.ctx != nullptr, PARAM_INVALID, "FabricMem AICPU slot context is null.");
305	  std::lock_guard<std::mutex> lock(pool_mutex_);
306	  for (auto &entry : slot_pool_) {
307	    if (entry.ctx != slot.ctx) {
308	      continue;
309	    }
310	    HIXL_CHK_BOOL_RET_STATUS(!entry.available, FAILED, "FabricMem AICPU slot is not acquired.");
311	    if (entry.sdma_streams.empty() || entry.notifies.empty()) {
312	      TemporaryRtContext with_context(entry.ctx);
313	      HIXL_DISMISSABLE_GUARD(resource_guard, ([&entry]() {
314	                               DestroySlotStreams(entry.sdma_streams, false, true);
315	                               DestroySlotNotifies(entry.notifies, entry.notify_ids);
316	                             }));
317	      if (entry.sdma_streams.empty()) {
318	        HIXL_CHK_STATUS_RET(PopulateAicpuRtsqStreams(entry), "Create FabricMem AICPU RTSQ worker streams failed.");
319	      }
320	      if (entry.notifies.empty()) {
321	        HIXL_CHK_STATUS_RET(PopulateAicpuNotifies(entry), "Create FabricMem AICPU notifies failed.");
322	      }
323	      HIXL_DISMISS_GUARD(resource_guard);
324	    }
325	    HIXL_CHK_BOOL_RET_STATUS(entry.sdma_streams.size() == entry.streams.size(), FAILED,
326	                             "FabricMem AICPU worker/control stream count mismatch.");
327	    HIXL_CHK_BOOL_RET_STATUS(
328	        entry.notifies.size() == entry.streams.size() && entry.notify_ids.size() == entry.streams.size(), FAILED,
329	        "FabricMem AICPU notify/control stream count mismatch.");
330	    slot.sdma_streams = entry.sdma_streams;
331	    slot.notifies = entry.notifies;
332	    slot.notify_ids = entry.notify_ids;
333	    return SUCCESS;
334	  }
335	  HIXL_LOGE(FAILED, "FabricMem AICPU slot is not managed by this pool.");
336	  return FAILED;
337	}
338	
339	void FabricMemSlotPool::ClearReleasedSlot(AsyncSlot &slot) {
340	  // slot only holds views of the pooled entry's resources, so just drop the
341	  // references here; the entry itself owns and reuses them.
342	  slot.ctx = nullptr;
343	  slot.streams.clear();
344	  slot.sdma_streams.clear();
345	  slot.notifies.clear();
346	  slot.notify_ids.clear();
347	  slot.host_flags.clear();
348	}
349	
350	void FabricMemSlotPool::RebuildFreeSlotIndicesLocked() {
351	  while (!free_slot_indices_.empty()) {
352	    free_slot_indices_.pop();
353	  }
354	  for (size_t i = 0U; i < slot_pool_.size(); ++i) {
355	    if (slot_pool_[i].available) {
356	      free_slot_indices_.push(i);
357	    }
358	  }
359	}
360	
361	bool FabricMemSlotPool::ReleaseSlotEntryLocked(AsyncSlot &slot, bool destroy_slot) {
362	  for (size_t i = 0U; i < slot_pool_.size(); ++i) {
363	    if (slot_pool_[i].ctx != slot.ctx) {
364	      continue;
365	    }
366	    if (destroy_slot) {
367	      DestroySlotEntryLocked(slot_pool_[i], true);
368	      slot_pool_.erase(slot_pool_.begin() + static_cast<ptrdiff_t>(i));
369	      RebuildFreeSlotIndicesLocked();
370	      return true;
371	    }
372	    slot_pool_[i].available = true;
373	    free_slot_indices_.push(i);
374	    return true;
375	  }
376	  return false;
377	}
378	
379	void FabricMemSlotPool::Release(AsyncSlot &slot, bool destroy_slot) {
380	  bool released = false;
381	  {
382	    std::lock_guard<std::mutex> lock(pool_mutex_);
383	    if (slot.ctx == nullptr) {
384	      ClearReleasedSlot(slot);
385	      return;
386	    }
387	    released = ReleaseSlotEntryLocked(slot, destroy_slot);
388	    ClearReleasedSlot(slot);
389	  }
390	  if (released) {
391	    pool_cv_.notify_one();
392	  }
393	}
394	
395	Status FabricMemSlotPool::AbortSlotStreams(const AsyncSlot &slot) {
396	  if (slot.ctx == nullptr) {
397	    return SUCCESS;
398	  }
399	  TemporaryRtContext with_context(slot.ctx);
400	  for (const auto &stream : slot.streams) {
401	    if (stream != nullptr) {
402	      HIXL_CHK_ACL_RET(aclrtStreamAbort(stream), "Abort FabricMem control stream failed.");
403	    }
404	  }
405	  // Worker RTSQ streams are ACL_STREAM_DEVICE_USE_ONLY: use StreamStop, not StreamAbort.
406	  for (const auto &stream : slot.sdma_streams) {
407	    if (stream != nullptr) {
408	      HIXL_CHK_ACL_RET(aclrtStreamStop(stream), "Stop FabricMem AICPU RTSQ worker stream failed.");
409	    }
410	  }
411	  return SUCCESS;
412	}
413	
414	void FabricMemSlotPool::SetAicpuDispatcher(FabricMemAicpuDispatcher *dispatcher) {
415	  std::lock_guard<std::mutex> lock(pool_mutex_);
416	  aicpu_dispatcher_ = dispatcher;
417	}
418	
419	FabricMemAicpuDispatcher *FabricMemSlotPool::GetAicpuDispatcher() const {
420	  std::lock_guard<std::mutex> lock(pool_mutex_);
421	  return aicpu_dispatcher_;
422	}
423	
424	bool FabricMemSlotPool::DetachSlotEntry(const AsyncSlot &slot, AsyncSlot &entry) {
425	  if (slot.ctx == nullptr) {
426	    return false;
427	  }
428	  std::lock_guard<std::mutex> lock(pool_mutex_);
429	  for (size_t i = 0U; i < slot_pool_.size(); ++i) {
430	    if (slot_pool_[i].ctx != slot.ctx) {
431	      continue;
432	    }
433	    entry = std::move(slot_pool_[i]);
434	    (void)slot_pool_.erase(slot_pool_.begin() + static_cast<ptrdiff_t>(i));
435	    RebuildFreeSlotIndicesLocked();
436	    // The pool has room again; a waiter can grow it while this entry is still being torn down.
437	    pool_cv_.notify_one();
438	    return true;
439	  }
440	  return false;
441	}
442	
443	void FabricMemSlotPool::DestroySlotEntryResources(AsyncSlot &entry) {
444	  TemporaryRtContext with_context(entry.ctx);
445	  // AbortSlot has already aborted / stopped these streams.
446	  DestroySlotStreams(entry.streams, false);
447	  DestroySlotStreams(entry.sdma_streams, false, true);
448	  DestroySlotNotifies(entry.notifies, entry.notify_ids);
449	  DestroySlotHostFlags(entry.host_flags);
450	}
451	
452	void FabricMemSlotPool::ReleaseRequestResources(const std::vector<FabricMemAicpuPendingRequest> &requests) {
453	  for (const auto &request : requests) {
454	    TemporaryRtContext with_context(request.slot != nullptr ? request.slot->ctx : nullptr);
455	    if (request.resource != nullptr) {
456	      FabricMemAicpuDispatcher::ReleaseRequestResource(*request.resource);
457	    }
458	    if (request.slot != nullptr) {
459	      DestroyOwnedHostFlags(*request.slot);
460	    }
461	  }
462	}
463	
464	void FabricMemSlotPool::AbortSlot(AsyncSlot &slot, const std::vector<FabricMemAicpuPendingRequest> &requests) {
465	  const AsyncSlot *const abort_slot = PickAbortSlot(slot, requests);
466	  AsyncSlot entry;
467	  bool detached = false;
468	  if (abort_slot != nullptr) {
469	    detached = DetachSlotEntry(*abort_slot, entry);
470	    HIXL_CHK_STATUS(AbortSlotStreams(*abort_slot), "Abort fabric mem slot streams failed.");
471	    FabricMemAicpuDispatcher *const dispatcher = GetAicpuDispatcher();
472	    if (dispatcher != nullptr) {
473	      // Waits out a kernel that still holds the TransferContext, so it can no longer read the
474	      // descriptor buffers freed below.
475	      HIXL_CHK_STATUS(dispatcher->DeleteTransferContext(*abort_slot),
476	                      "FabricMem AICPU delete transfer context failed during slot abort.");
477	    }
478	  }
479	  if (detached) {
480	    DestroySlotEntryResources(entry);
481	  }
482	  ReleaseRequestResources(requests);
483	  if (detached && entry.ctx != nullptr) {
484	    HIXL_CHK_ACL(aclrtDestroyContext(entry.ctx), "Destroy fabric mem transfer context failed.");
485	    entry.ctx = nullptr;
486	  }
487	  slot = AsyncSlot{};
488	}
489	
490	void FabricMemSlotPool::DestroyOwnedHostFlags(AsyncSlot &slot) {
491	  if (!slot.owns_host_flags) {
492	    return;
493	  }
494	  for (void *host_flag : slot.host_flags) {
495	    if (host_flag != nullptr) {
496	      HIXL_CHK_ACL(aclrtFreeHost(host_flag), "Free fabric mem transfer host flag failed.");
497	    }
498	  }
499	  slot.host_flags.clear();
500	  slot.owns_host_flags = false;
501	}
502	
503	void FabricMemSlotPool::AbortAndDestroyAll() {
504	  std::lock_guard<std::mutex> lock(pool_mutex_);
505	  for (auto &entry : slot_pool_) {
506	    DestroySlotEntryLocked(entry, true);
507	  }
508	  slot_pool_.clear();
509	  while (!free_slot_indices_.empty()) {
510	    free_slot_indices_.pop();
511	  }
512	  pool_cv_.notify_all();
513	}
514	}  // namespace hixl
