50	  const size_t requested = capacity_in_tb * kBytesPerTB;
51	  if (initialized_) {
52	    HIXL_CHK_BOOL_RET_STATUS(vm_size_ == requested, PARAM_INVALID,
53	                             "VirtualMemoryManager already initialized, cannot set capacity.");
54	    return SUCCESS;
55	  }
56	  vm_size_ = requested;
57	  num_blocks_ = vm_size_ / kBlockSize;
58	  HIXL_LOGI("Set virtual memory capacity to %zu TB, bytes:%zu, blocks:%zu.", capacity_in_tb, vm_size_, num_blocks_);
59	  return SUCCESS;
