64	  HIXL_CHK_BOOL_RET_STATUS(start_addr_in_tb <= kMaxFabricMemStartAddrTB, PARAM_INVALID,
65	                           "global start address must be in [%zu, %zu] TB, got %zu.", kMinFabricMemStartAddrTB,
66	                           kMaxFabricMemStartAddrTB, start_addr_in_tb);
67	  const uintptr_t requested = start_addr_in_tb * kBytesPerTB;
68	  if (initialized_) {
69	    HIXL_CHK_BOOL_RET_STATUS(global_start_va_.value_or(kGlobalVirtualMemoryStartAddr) == requested, PARAM_INVALID,
70	                             "VirtualMemoryManager already initialized, cannot set global start address.");
71	    return SUCCESS;
72	  }
73	  global_start_va_ = requested;
74	  HIXL_LOGI("Set global virtual memory start address to %zu TB, bytes:%lu.", start_addr_in_tb, requested);
