79	  const uintptr_t start_va = global_start_va_.value_or(kGlobalVirtualMemoryStartAddr);
80	  void *global_start_va = reinterpret_cast<void *>(start_va);
81	  if (IsA3Soc() && &aclrtReserveMemAddressNoUCMemory != nullptr) {
82	    auto ret = aclrtReserveMemAddressNoUCMemory(&virtual_address, size, 0, global_start_va, kReserveFlagHugePage);
83	    if (ret == ACL_ERROR_NONE) {
84	      HIXL_LOGI("Reserve virtual memory without UC memory on A3, size:%zu.", size);
85	      return SUCCESS;
86	    }
87	    HIXL_CHK_BOOL_RET_STATUS(ret == ACL_ERROR_RT_FEATURE_NOT_SUPPORT, FAILED,
88	                             "Call api:aclrtReserveMemAddressNoUCMemory failed, ret:%d, size:%zu bytes", ret, size);
89	  }
90	  HIXL_CHK_ACL_RET(aclrtReserveMemAddress(&virtual_address, size, 0, nullptr, kReserveFlagHugePage),
91	                   "Reserve virtual memory failed.");
92	  HIXL_LOGI("Reserve virtual memory with aclrtReserveMemAddress, size:%zu.", size);
