105	Status VirtualMemoryManager::InitProcess() {
106	  if (vm_size_ == 0) {
107	    vm_size_ = kDefaultGlobalVirtualMemorySize;
108	    num_blocks_ = kDefaultNumBlocks;
109	  }
110	  HIXL_CHK_STATUS_RET(ReserveMemAddress(global_virtual_memory_, vm_size_), "Failed to reserve global virtual memory.");
111	  global_virtual_memory_addr_ = reinterpret_cast<uintptr_t>(global_virtual_memory_);
112	  bitmap_.assign(num_blocks_, false);
113	  allocations_.clear();
114	  initialized_ = true;
115	  HIXL_LOGI("VirtualMemoryManager initialized, base virtual address:%lu.", global_virtual_memory_addr_);
116	  return SUCCESS;
