119	void VirtualMemoryManager::Finalize() {
120	  std::lock_guard<std::mutex> lock(global_virtual_memory_mutex_);
121	  if (!initialized_) {
122	    return;
123	  }
124	  bitmap_.clear();
125	  allocations_.clear();
126	  initialized_ = false;
127	  if (global_virtual_memory_ != nullptr) {
128	    HIXL_CHK_ACL(aclrtReleaseMemAddress(global_virtual_memory_), "Release global virtual memory failed.");
129	    global_virtual_memory_ = nullptr;
130	    global_virtual_memory_addr_ = 0;
131	  }
132	}
