134	Status VirtualMemoryManager::ReserveMemory(size_t size, uintptr_t &mem_addr) {
135	  std::lock_guard<std::mutex> lock(global_virtual_memory_mutex_);
136	  HIXL_CHK_BOOL_RET_STATUS(size > 0, PARAM_INVALID, "ReserveMemory size cannot be zero.");
137	  if (!initialized_) {
138	    HIXL_CHK_STATUS_RET(InitProcess(), "Failed to initialize virtual memory process.");
139	  }
140	  // Use ceil-division instead of (size + kBlockSize - 1) so a size close to SIZE_MAX cannot wrap around and yield a
141	  // tiny blocks_needed that bypasses the capacity check below (which would later allow an out-of-bounds access).
142	  const size_t blocks_needed = size / kBlockSize + ((size % kBlockSize != 0U) ? 1UL : 0UL);
143	  HIXL_CHK_BOOL_RET_STATUS(blocks_needed <= num_blocks_, RESOURCE_EXHAUSTED,
144	                           "Requested size %zu exceeds virtual memory capacity.", size);
145	
146	  size_t start_block = 0;
147	  size_t contiguous_free = 0;
148	  for (size_t i = 0; i < num_blocks_; ++i) {
149	    if (!bitmap_[i]) {
150	      if (contiguous_free == 0) {
151	        start_block = i;
152	      }
153	      ++contiguous_free;
154	      if (contiguous_free >= blocks_needed) {
155	        break;
156	      }
157	      continue;
158	    }
159	    contiguous_free = 0;
160	  }
161	  HIXL_CHK_BOOL_RET_STATUS(contiguous_free >= blocks_needed, RESOURCE_EXHAUSTED,
162	                           "Insufficient contiguous virtual memory blocks, needed:%zu.", blocks_needed);
163	
164	  for (size_t i = start_block; i < start_block + blocks_needed; ++i) {
165	    bitmap_[i] = true;
166	  }
167	  mem_addr = global_virtual_memory_addr_ + start_block * kBlockSize;
168	  allocations_[mem_addr] = blocks_needed;
169	  HIXL_LOGI("Reserved %zu bytes, blocks:%zu, address:%lu.", size, blocks_needed, mem_addr);
170	  return SUCCESS;
171	}
