173	Status VirtualMemoryManager::ReleaseMemory(uintptr_t mem_addr) {
174	  std::lock_guard<std::mutex> lock(global_virtual_memory_mutex_);
175	  HIXL_CHK_BOOL_RET_STATUS(initialized_, PARAM_INVALID, "VirtualMemoryManager is not initialized.");
176	  HIXL_CHK_BOOL_RET_STATUS(mem_addr >= global_virtual_memory_addr_ && mem_addr < global_virtual_memory_addr_ + vm_size_,
177	                           PARAM_INVALID, "Address %lu is outside managed virtual memory range.", mem_addr);
178	  HIXL_CHK_BOOL_RET_STATUS((mem_addr - global_virtual_memory_addr_) % kBlockSize == 0, PARAM_INVALID,
179	                           "Address %lu is not 1GB aligned.", mem_addr);
180	  const auto it = allocations_.find(mem_addr);
181	  HIXL_CHK_BOOL_RET_STATUS(it != allocations_.end(), PARAM_INVALID, "Address %lu is not allocated or already released.",
182	                           mem_addr);
183	
184	  const size_t block_index = (mem_addr - global_virtual_memory_addr_) / kBlockSize;
185	  for (size_t i = block_index; i < block_index + it->second; ++i) {
186	    bitmap_[i] = false;
187	  }
188	  HIXL_LOGI("Released %zu blocks from address:%lu.", it->second, mem_addr);
189	  allocations_.erase(it);
190	  return SUCCESS;
191	}
