76	                                                          bool &is_duplicate) const {
77	  AddrInfo cur_info{};
78	  HIXL_CHK_STATUS_RET(BuildRegisteredAddrInfo(mem.addr, mem.len, type, cur_info),
79	                      "Invalid fabric mem registration range.");
80	  std::lock_guard<std::mutex> lock(share_handle_mutex_);
81	  std::map<MemHandle, AddrInfo> addr_map;
82	  for (const auto &item : share_handles_) {
83	    AddrInfo registered_info{};
84	    HIXL_CHK_STATUS_RET(
85	        BuildRegisteredAddrInfo(item.second.va_addr, item.second.len, item.second.mem_type, registered_info),
86	        "Registered fabric mem range is invalid.");
87	    addr_map[item.first] = registered_info;
88	  }
89	  MemHandle existing_handle = nullptr;
90	  HIXL_CHK_STATUS_RET(CheckAddrOverlap(cur_info, addr_map, is_duplicate, existing_handle),
91	                      "Failed to check fabric mem address overlap.");
