98	Status FabricMemLocalMemory::RegisterMem(const MemDesc &mem, MemType type, MemHandle &mem_handle) {
99	  HIXL_CHK_BOOL_RET_STATUS(mem.addr != 0 && mem.len > 0, PARAM_INVALID, "Invalid fabric mem registration range.");
100	  bool is_duplicate = false;
101	  HIXL_CHK_STATUS_RET(FindExistingHandleForOverlap(mem, type, mem_handle, is_duplicate),
102	                      "Failed to check fabric mem address overlap.");
103	  if (is_duplicate) {
104	    return SUCCESS;
105	  }
106	  aclrtDrvMemHandle pa_handle = nullptr;
107	  bool is_retained = false;
108	  if (FabricMemAllocator::GetPaHandleFromVa(mem.addr, pa_handle) != SUCCESS) {
109	    HIXL_CHK_ACL_RET(aclrtMemRetainAllocationHandle(reinterpret_cast<void *>(mem.addr), &pa_handle),
110	                     "Retain allocation handle failed.");
111	    is_retained = true;
112	  }
113	  aclrtDrvMemHandle imported_pa_handle = nullptr;
114	  uintptr_t imported_va = 0;
115	  HIXL_DISMISSABLE_GUARD(fail_guard, ([&pa_handle, &is_retained, &imported_va, &imported_pa_handle]() {
116	                           CleanupRegisterMemFailure(pa_handle, is_retained, imported_va, imported_pa_handle);
117	                         }));
118	
119	  aclrtMemFabricHandle share_handle = {};
120	  HIXL_CHK_ACL_RET(aclrtMemExportToShareableHandleV2(pa_handle, ACL_RT_VMM_EXPORT_FLAG_DISABLE_PID_VALIDATION,
121	                                                     ACL_MEM_SHARE_HANDLE_TYPE_FABRIC, &share_handle),
122	                   "Export fabric share handle failed.");
123	  if (type == MEM_HOST) {
124	    HIXL_CHK_STATUS_RET(ImportHostMemoryForRegister(mem, share_handle, imported_pa_handle, imported_va),
125	                        "Import host memory for register failed.");
126	  }
127	
128	  {
129	    std::lock_guard<std::mutex> lock(share_handle_mutex_);
130	    share_handles_[pa_handle] = {mem.addr, mem.len, share_handle, imported_pa_handle, imported_va, is_retained, type};
131	  }
132	  if (type == MEM_HOST) {
133	    has_host_memory_.store(true);
134	  }
135	  mem_handle = pa_handle;
136	  HIXL_LOGI("Register fabric mem success, type:%s, addr:%lu, len:%zu, retained:%d, handle:%p.",
137	            MemTypeToString(type).c_str(), mem.addr, mem.len, static_cast<int32_t>(is_retained), mem_handle);
138	  HIXL_DISMISS_GUARD(fail_guard);
139	  return SUCCESS;
140	}
