142	Status FabricMemLocalMemory::DeregisterMem(MemHandle mem_handle) {
143	  std::lock_guard<std::mutex> lock(share_handle_mutex_);
144	  const auto it = share_handles_.find(static_cast<aclrtDrvMemHandle>(mem_handle));
145	  if (it == share_handles_.end()) {
146	    HIXL_LOGW("Fabric mem handle:%p is not registered.", mem_handle);
147	    return SUCCESS;
148	  }
149	  const auto info = it->second;
150	  if (info.imported_va != 0) {
151	    HIXL_CHK_ACL(aclrtUnmapMem(reinterpret_cast<void *>(info.imported_va)), "Unmap local host mapping failed.");
152	    (void)VirtualMemoryManager::GetInstance().ReleaseMemory(info.imported_va);
153	  }
154	  if (info.imported_handle != nullptr) {
155	    HIXL_CHK_ACL(aclrtFreePhysical(info.imported_handle), "Free imported local handle failed.");
156	  }
157	  if (info.is_retained) {
158	    HIXL_CHK_ACL(aclrtFreePhysical(static_cast<aclrtDrvMemHandle>(mem_handle)), "Free retained handle failed.");
159	  }
160	  share_handles_.erase(it);
161	  HIXL_LOGI("Deregister fabric mem success, handle:%p.", mem_handle);
162	  return SUCCESS;
