179	bool FabricMemLocalMemory::FindLocalHostRegisteredAddrLocked(uintptr_t old_addr, size_t len,
180	                                                             uintptr_t &new_addr) const {
181	  for (const auto &item : share_handles_) {
182	    const auto &info = item.second;
183	    if (info.imported_va == 0) {
184	      continue;
185	    }
186	    if (!IsRangeContained(old_addr, len, info.va_addr, info.len)) {
187	      continue;
188	    }
189	    new_addr = info.imported_va + (old_addr - info.va_addr);
190	    return true;
191	  }
192	  return false;
