226	Status FabricMemRemoteMemory::Import(const std::vector<ShareHandleInfo> &remote_share_handles, int32_t device_id) {
227	  std::lock_guard<std::mutex> lock(mutex_);
228	  HIXL_DISMISSABLE_GUARD(fail_guard, ([this]() { ClearLocked(); }));
229	  for (const auto &remote_share_handle_info : remote_share_handles) {
230	    uintptr_t remote_va_addr = 0;
231	    aclrtDrvMemHandle remote_pa_handle = nullptr;
232	    HIXL_CHK_STATUS_RET(VirtualMemoryManager::GetInstance().ReserveMemory(remote_share_handle_info.len, remote_va_addr),
233	                        "Reserve memory for remote share handle failed.");
234	    HIXL_DISMISSABLE_GUARD(free_mem_guard, ([&remote_va_addr, &remote_pa_handle]() {
235	                             if (remote_va_addr != 0) {
236	                               (void)VirtualMemoryManager::GetInstance().ReleaseMemory(remote_va_addr);
237	                             }
238	                             if (remote_pa_handle != nullptr) {
239	                               HIXL_CHK_ACL(aclrtFreePhysical(remote_pa_handle),
240	                                            "Free imported remote pa handle failed.");
241	                             }
242	                           }));
243	
244	    auto share_handle = remote_share_handle_info.share_handle;
245	    HIXL_CHK_ACL_RET(
246	        aclrtMemImportFromShareableHandleV2(&share_handle, ACL_MEM_SHARE_HANDLE_TYPE_FABRIC, 0U, &remote_pa_handle),
247	        "Import remote fabric share handle failed.");
248	    HIXL_CHK_ACL_RET(
249	        aclrtMapMem(reinterpret_cast<void *>(remote_va_addr), remote_share_handle_info.len, 0, remote_pa_handle, 0),
250	        "Map remote imported memory failed.");
251	    remote_pa_handles_.emplace_back(remote_pa_handle);
252	    new_va_to_old_va_[remote_va_addr] = {remote_share_handle_info.va_addr, remote_share_handle_info.len};
253	    HIXL_DISMISS_GUARD(free_mem_guard);
254	    HIXL_LOGI("Imported remote fabric mem, old va:%lu, mapped va:%lu, len:%zu, handle:%p, device:%d.",
255	              remote_share_handle_info.va_addr, remote_va_addr, remote_share_handle_info.len, remote_pa_handle,
256	              device_id);
257	  }
258	  HIXL_DISMISS_GUARD(fail_guard);
259	  return SUCCESS;
260	}
261	
262	void FabricMemRemoteMemory::ClearLocked() {
263	  for (const auto &it : new_va_to_old_va_) {
264	    HIXL_LOGI("Unmap remote fabric mem:%lu.", it.first);
265	    HIXL_CHK_ACL(aclrtUnmapMem(reinterpret_cast<void *>(it.first)), "Unmap remote fabric mem failed.");
266	    (void)VirtualMemoryManager::GetInstance().ReleaseMemory(it.first);
267	  }
268	  new_va_to_old_va_.clear();
269	  for (auto &remote_pa_handle : remote_pa_handles_) {
270	    HIXL_CHK_ACL(aclrtFreePhysical(remote_pa_handle), "Free imported remote pa handle failed.");
271	    HIXL_LOGI("Free imported remote handle:%p.", remote_pa_handle);
272	  }
273	  remote_pa_handles_.clear();
274	}
