12	#define CANN_HIXL_SRC_HIXL_FABRIC_MEM_FABRIC_MEM_SLOT_POOL_H_
13	
14	#include <condition_variable>
15	#include <mutex>
16	#include <queue>
17	#include <vector>
18	
19	#include "acl/acl.h"
20	#include "fabric_mem/fabric_mem_types.h"
21	#include "hixl/hixl_types.h"
22	
23	namespace hixl {
24	
25	class FabricMemAicpuDispatcher;
26	
27	// Bounded pool of reusable transfer slots (each slot owns a context, task streams and host completion
28	// flags). Acquired slots are views into pooled entries; release returns them for reuse or destroys
29	// them (aborting their streams). Shared by the transfer service (acquire/release during a transfer)
30	// and the channel manager (abort/release during disconnect).
31	class FabricMemSlotPool {
32	 public:
33	  FabricMemSlotPool() = default;
34	  ~FabricMemSlotPool();
35	  FabricMemSlotPool(const FabricMemSlotPool &) = delete;
36	  FabricMemSlotPool &operator=(const FabricMemSlotPool &) = delete;
37	  FabricMemSlotPool(FabricMemSlotPool &&) = delete;
38	  FabricMemSlotPool &operator=(FabricMemSlotPool &&) = delete;
39	
40	  Status Initialize(int32_t device_id, size_t max_async_slot_num, size_t task_stream_num);
41	  Status AcquireWithTimeout(AsyncSlot &slot, uint64_t timeout_us);
42	  Status AcquireAsync(AsyncSlot &slot);
43	  // Lazily creates one device-only A3 RTSQ worker stream per control stream.
44	  // Keeping these absent from the default path preserves its existing resource footprint.
45	  Status EnsureAicpuRtsqStreams(AsyncSlot &slot);
46	  void Release(AsyncSlot &slot, bool destroy_slot);
47	  void AbortAndDestroyAll();
48	  // AICPU unfold only: lets AbortSlot force a running kernel to exit before the slot goes away.
49	  void SetAicpuDispatcher(FabricMemAicpuDispatcher *dispatcher);
50	  // The single abort path for a slot that may still carry in-flight AICPU work. Both the transfer
51	  // failure paths and disconnect go through it, in this fixed order:
52	  //   1. abort the control streams and stop the device-only RTSQ worker streams,
53	  //   2. delete the AICPU TransferContext so a kernel that is mid-submit exits,
54	  //   3. destroy the slot's streams and notifies instead of returning them to the pool,
55	  //   4. free the descriptor / status buffers and per-transfer host flags of `requests`,
56	  //   5. destroy the slot context.
57	  // Steps 1-2 must precede step 4: the kernel reads the descriptor buffer, and step 4 must precede
58	  // step 5 because the buffers were allocated under this context.
59	  void AbortSlot(AsyncSlot &slot, const std::vector<FabricMemAicpuPendingRequest> &requests);
60	  // Frees per-request descriptor / status buffers and per-transfer host flags. Only safe on its own
61	  // once the AICPU kernel can no longer reach them (otherwise go through AbortSlot).
62	  static void ReleaseRequestResources(const std::vector<FabricMemAicpuPendingRequest> &requests);
63	  // Stops in-flight work on a slot without returning it to the pool: aborts control
64	  // streams and stops device-only RTSQ worker streams (cannot aclrtStreamAbort those).
65	  static Status AbortSlotStreams(const AsyncSlot &slot);
66	  // Frees per-transfer host flags when slot.owns_host_flags is true.
67	  static void DestroyOwnedHostFlags(AsyncSlot &slot);
68	
69	 private:
70	  static Status CreateSlotStream(aclrtStream &stream);
71	  static Status CreateAicpuRtsqStream(aclrtStream &stream);
72	  static void DestroySlotStreams(std::vector<aclrtStream> &streams, bool abort_streams, bool device_only = false);
73	  static void DestroySlotNotifies(std::vector<aclrtNotify> &notifies, std::vector<uint32_t> &notify_ids);
74	  static void DestroySlotHostFlags(std::vector<void *> &host_flags);
75	  static void ResetSlotHostFlags(const std::vector<void *> &host_flags);
76	  static void DestroyCreatedSlotEntry(AsyncSlot &entry);
77	  Status PopulateSlotStreams(AsyncSlot &entry) const;
78	  Status PopulateAicpuRtsqStreams(AsyncSlot &entry) const;
79	  Status PopulateAicpuNotifies(AsyncSlot &entry) const;
80	  Status PopulateSlotHostFlags(AsyncSlot &entry) const;
81	  Status CreateSlotEntryLocked(AsyncSlot &entry) const;
82	  void DestroySlotEntryLocked(AsyncSlot &entry, bool abort_streams) const;
83	  Status TryAcquireSlotLocked(AsyncSlot &slot);
84	  void RebuildFreeSlotIndicesLocked();
85	  bool ReleaseSlotEntryLocked(AsyncSlot &slot, bool destroy_slot);
86	  static void ClearReleasedSlot(AsyncSlot &slot);
87	  // Removes the pooled entry backing `slot` so nobody can acquire it while it is being aborted.
88	  bool DetachSlotEntry(const AsyncSlot &slot, AsyncSlot &entry);
89	  FabricMemAicpuDispatcher *GetAicpuDispatcher() const;
90	  // Destroys the entry's streams / notifies / pooled host flags but keeps its context alive.
91	  static void DestroySlotEntryResources(AsyncSlot &entry);
92	
93	  mutable std::mutex pool_mutex_;
94	  std::condition_variable pool_cv_;
95	  std::vector<AsyncSlot> slot_pool_;
96	  std::queue<size_t> free_slot_indices_;
97	
98	  int32_t device_id_{-1};
99	  size_t max_async_slot_num_{0};
100	  size_t task_stream_num_{0};
101	  // Set once at service initialization, before any channel exists; read by AbortSlot.
102	  FabricMemAicpuDispatcher *aicpu_dispatcher_{nullptr};
